/* Verified official headlines, with publisher links. No invented images. */
(()=>{'use strict';const stories=[
{date:'21 November 2026',category:'Sports',title:'Africa Safe Sport and Women Empowerment Initiative launched in Mauritius',summary:'The Government Information Service reports the launch of an initiative focused on safer, more inclusive sport and women’s empowerment.',url:'https://gis.govmu.org/gis/?page_id=1917'},
{date:'20 November 2026',category:'Agriculture',title:'Authorities strengthen livestock protection measures',summary:'Government reports strengthened measures following suspected cases of foot-and-mouth disease. Read the official notice for details.',url:'https://gis.govmu.org/gis/?page_id=1917'},
{date:'20 November 2026',category:'Media & technology',title:'Media Trust presents charter on responsible AI in journalism',summary:'A new charter aims to guide responsible use of artificial intelligence by media professionals, according to the Government Information Service.',url:'https://gis.govmu.org/gis/?page_id=1917'}
];const ready=()=>{const main=document.querySelector('#homePage');if(!main||document.getElementById('imVerifiedDesk'))return;const section=document.createElement('section');section.id='imVerifiedDesk';section.className='im-verified-desk';section.setAttribute('aria-labelledby','imVerifiedTitle');const head=document.createElement('div');head.className='im-verified-desk__head';head.innerHTML='<div><span class="im-verified-desk__eyebrow">INSIDE MAURITIUS · VERIFIED SOURCES</span><h2 id="imVerifiedTitle">Latest official Mauritius updates</h2><p>Source-dated reports · 20–21 November 2026</p></div>';section.append(head);const grid=document.createElement('div');grid.className='im-verified-desk__grid';stories.forEach(s=>{const card=document.createElement('article');card.className='im-verified-desk__card';const meta=document.createElement('span');meta.className='im-verified-desk__meta';meta.textContent=s.category+' · '+s.date;const title=document.createElement('h3');title.textContent=s.title;const desc=document.createElement('p');desc.textContent=s.summary;const link=document.createElement('a');link.href=s.url;link.target='_blank';link.rel='noopener noreferrer';link.textContent='Read official source';card.append(meta,title,desc,link);grid.append(card)});section.append(grid);const note=document.createElement('p');note.className='im-verified-desk__note';note.textContent='Source: Mauritius Government Information Service. Dates reflect the original reports, not a live update feed. Existing Inside Mauritius news, photos and branding remain unchanged.';section.append(note);const first=main.querySelector('section');if(first)first.insertAdjacentElement('afterend',section);else main.prepend(section)};if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',ready,{once:true});else ready()})();